  vWorldPos = pos;
  vWorldNormal = n;
  vHeight = pos.y - world.y;
  vCrest = saturate((1.0 - n.y) * 1.8 + vHeight * 0.35);
  gl_Position = projectionMatrix * viewMatrix * vec4(pos, 1.0);
